package com.sudpanel.perf;

import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.sudpanel.api.*;
import java.util.*;
import org.junit.jupiter.api.Test;

class PerfSettlementRulesTest {
 final String id="12345678901234567890123456789012345678";
 final PerfSettlementService service=new PerfSettlementService(mock(PerfRepository.class),mock(PerfEvidenceRepository.class),mock(ApiRepository.class),mock(ApiRunner.class));
 PerfExecutionPlan plan(){return new PerfExecutionPlan(1,"START","2026-10-14T00:00:00Z","NORMAL",1,5,1L,null,null,List.of(1L),Map.of(1L,Map.of("roomId","room","mgId","9223372036854775807")),Map.of(),Map.of(),Map.of(),Map.of(),1000,1,1,3);}
 Map<String,Object> loop(){return Map.of("gameId",1L,"gameRoundId",id,"startTime","2026-10-14T00:00:00Z","endTime","2026-10-14T00:01:00Z");}
 PerfSettlementService.Rules rules(String participants){return rules(participants,new PerfParticipationEvidence.Rules("start","id","room","game","players","uid",true,"",""));}
 PerfSettlementService.Rules rules(String participants,PerfParticipationEvidence.Rules source){return new PerfSettlementService.Rules("data","id","room","game","players","uid","time","ISO","code",List.of("0"),List.of("202"),List.of("404"),participants,0L,source);}
 ApiExec result(String body){return new ApiExec(null,null,1L,"query",1,1,"POST","http://127.0.0.1/fake",200,"0","success","PASS",null,1L,body,"{}","{}","{}",null,"2026-10-14T00:00:00Z",null,"{}");}
 String record(String room,String players,String time){return "{\"id\":\""+id+"\",\"room\":\""+room+"\",\"game\":9223372036854775807,\"players\":"+players+",\"time\":\""+time+"\",\"seatCapacity\":4}";}
 String body(String room,String players,String time){return "{\"code\":0,\"data\":"+record(room,players,time)+",\"start\":"+record("room",players,time)+"}";}
 String roster(String... ids){return "["+String.join(",",Arrays.stream(ids).map(uid->"{\"uid\":\""+uid+"\"}").toList())+"]";}
 Map<String,Object> evaluate(String body,PerfSettlementService.Rules rule,Set<String> candidates){return service.evaluate(loop(),plan(),rule,result(body),0,candidates);}
 String good(){return body("room",roster("A","B","C","D"),"2026-10-14T00:00:30Z");}
 Set<String> eight(){return new LinkedHashSet<>(List.of("A","B","C","D","E","F","G","H"));}
 @Test void eightCandidatesFourActualPlayersPassExactWithoutSelectingFirstFour(){var checked=evaluate(good(),rules("EXACT"),eight());assertThat(checked).containsEntry("status","SUCCESS").containsEntry("semanticsVersion",2);assertThat((Map<String,Object>)checked.get("participantEvidence")).containsEntry("candidateCount",8).containsEntry("actualParticipantCount",4).containsEntry("settlementCount",4);}
 @Test void arbitraryFourFromEightNeedMatchingFullStartReportNotPushOrder(){var checked=evaluate(body("room",roster("H","D","F","B"),"2026-10-14T00:00:30Z"),rules("EXACT"),eight());assertThat(checked).containsEntry("status","SUCCESS");}
 @Test void oldExactWithoutActualEvidenceIsUnknownEvenIfAllCandidatesMatch(){assertThat(evaluate(good(),rules("EXACT",null),Set.of("A","B","C","D"))).containsEntry("status","UNKNOWN");}
 @Test void oldSubsetCannotPassWithoutActualEvidence(){assertThat(evaluate(good(),rules("SUBSET_ALLOWED",null),eight())).containsEntry("status","UNKNOWN");}
 @Test void oldSubsetWithRealEvidenceStillRequiresActualExact(){String response=good().replace("\"start\":"+record("room",roster("A","B","C","D"),"2026-10-14T00:00:30Z"),"\"start\":"+record("room",roster("A","B","C"),"2026-10-14T00:00:30Z"));assertThat(evaluate(response,rules("SUBSET_ALLOWED"),eight())).containsEntry("status","MISMATCH");}
 @Test void actualRosterCanVerifyWhenCandidateEvidenceUnavailable(){assertThat(evaluate(good(),rules("EXACT"),null)).containsEntry("status","SUCCESS");}
 @Test void capacityOnlyChecksUpperBoundAndCandidatesButOverallRemainsUnknown(){var source=new PerfParticipationEvidence.Rules("start","id","room","game","players","uid",false,"seatCapacity","explicit mock report contract");var checked=evaluate(good(),rules("EXACT",source),eight());assertThat(checked).containsEntry("status","UNKNOWN");assertThat((Map<String,Object>)checked.get("participantEvidence")).containsEntry("capacity",4).containsEntry("actualParticipantCount",null);assertThat((List<Map<String,Object>>)checked.get("checks")).anyMatch(c->"capacity".equals(c.get("field"))&&"PASS".equals(c.get("status")));}
 @Test void capacityOverrunAndNonCandidateAreMismatches(){var source=new PerfParticipationEvidence.Rules("start","id","room","game","players","uid",false,"seatCapacity","explicit contract");assertThat(evaluate(good().replace("\"seatCapacity\":4","\"seatCapacity\":3"),rules("EXACT",source),eight())).containsEntry("status","MISMATCH");assertThat(evaluate(good(),rules("EXACT",source),Set.of("A","B","C"))).containsEntry("status","MISMATCH");}
 @Test void missingCapacityProvenanceIsNeverInvented(){var source=new PerfParticipationEvidence.Rules("start","id","room","game","players","uid",false,"seatCapacity","");var checked=evaluate(good(),rules("EXACT",source),eight());assertThat(checked).containsEntry("status","UNKNOWN");assertThat((Map<String,Object>)checked.get("participantEvidence")).containsEntry("capacity",null).containsEntry("capacitySource","NOT_RECORDED");}
 @Test void incompleteStartRosterAndMissingStartAreUnknown(){var source=new PerfParticipationEvidence.Rules("start","id","room","game","players","uid",false,"","");assertThat(evaluate(good(),rules("EXACT",source),eight())).containsEntry("status","UNKNOWN");assertThat(evaluate(good().replace("\"start\"","\"absent\""),rules("EXACT"),eight())).containsEntry("status","UNKNOWN");}
 @Test void reportCannotUseSettlementAsItsOwnEvidenceIncludingPathAliases(){for(String path:List.of("data","$.data"," data ","data..","$","$.")){var source=new PerfParticipationEvidence.Rules(path,"id","room","game","players","uid",true,"","");assertThat(evaluate(good(),rules("EXACT",source),eight())).containsEntry("status","UNKNOWN");}}
 @Test void wrongStartRoundRoomAndGameCannotPass(){for(String changed:List.of(record("wrong",roster("A","B","C","D"),"2026-10-14T00:00:30Z"),record("room",roster("A","B","C","D"),"2026-10-14T00:00:30Z").replace(id,"other-round"),record("room",roster("A","B","C","D"),"2026-10-14T00:00:30Z").replace("9223372036854775807","9223372036854775806"))){String response="{\"code\":0,\"data\":"+record("room",roster("A","B","C","D"),"2026-10-14T00:00:30Z")+",\"start\":"+changed+"}";assertThat(evaluate(response,rules("EXACT"),eight())).containsEntry("status","MISMATCH");}}
 @Test void missingStartIdentityIsUnknown(){String response=good().replace("\"start\":"+record("room",roster("A","B","C","D"),"2026-10-14T00:00:30Z"),"\"start\":"+record("room",roster("A","B","C","D"),"2026-10-14T00:00:30Z").replace("\"room\":\"room\",",""));assertThat(evaluate(response,rules("EXACT"),eight())).containsEntry("status","UNKNOWN");}
 @Test void duplicateUidIsMismatchButEmptyOrMixedUidTypesRemainUnknown(){assertThat(evaluate(body("room",roster("A","A"),"2026-10-14T00:00:30Z"),rules("EXACT"),eight())).containsEntry("status","MISMATCH");for(String players:List.of("[]","[{\"uid\":\"A\"},{\"uid\":9223372036854775807}]","[{\"uid\":\"\"}]","[{\"uid\":true}]"))assertThat(evaluate(body("room",players,"2026-10-14T00:00:30Z"),rules("EXACT"),eight())).containsEntry("status","UNKNOWN");}
 @Test void longStringUidAndBigIntegerGameIdentityAreComparedWithoutPrecisionLoss(){String uid="123456789012345678901234567890";assertThat(evaluate(body("room",roster(uid),"2026-10-14T00:00:30Z"),rules("EXACT"),Set.of(uid))).containsEntry("status","SUCCESS");}
 @Test void http200PendingAndMissingAreDifferentFromVerifiedSettlement(){assertThat(evaluate("{\"code\":202}",rules("EXACT"),Set.of())).containsEntry("status","PENDING");assertThat(evaluate("{\"code\":0,\"data\":null}",rules("EXACT"),Set.of())).containsEntry("status","NO_DATA");assertThat(evaluate("{\"code\":404}",rules("EXACT"),Set.of())).containsEntry("status","NO_DATA");}
 @Test void wrongRoomOrTimeCannotBeGreen(){assertThat(evaluate(body("wrong",roster("A"),"2026-10-14T00:00:30Z"),rules("EXACT"),Set.of("A"))).containsEntry("status","MISMATCH");assertThat(evaluate(body("room",roster("A"),"2026-10-15T00:00:30Z"),rules("EXACT"),Set.of("A"))).containsEntry("status","MISMATCH");}
 @Test void roundTemplateKeepsLongIdAndMissingRecordUnknown(){var spec=new ApiSpec(1L,"query","POST","http://127.0.0.1/fake","{}","{\"game_round_id\":1}",null,"200",null,1000,false,true,null,null);assertThat(service.fillRound(spec,id).body()).contains("\""+id+"\"");assertThat(evaluate("{\"code\":0}",rules("EXACT"),eight())).containsEntry("status","UNKNOWN");}
 @Test void summaryTruncatesOversizedActualIdentityExplicitly(){var checked=evaluate(good().replace(id,"x".repeat(10000)),rules("EXACT"),eight());assertThat(checked).containsEntry("status","MISMATCH");assertThat(checked.toString()).hasSizeLessThan(15000);assertThat((List<Map<String,Object>>)checked.get("checks")).anyMatch(c->Boolean.TRUE.equals(c.get("actualTruncated")));}
 @Test void duplicateJsonIdentityFieldsCannotCreateAFalseGreen(){assertThat(evaluate(good().replace("\"id\":", "\"id\":\"different\",\"id\":"),rules("EXACT"),eight())).containsEntry("status","UNKNOWN");}

 @Test void wildcardArrayAliasCannotValidateARecordAgainstItself(){var source=new PerfParticipationEvidence.Rules("data[ * ]","id","room","game","players","uid",true,"","");var rules=new PerfSettlementService.Rules("data[0]","id","room","game","players","uid","time","ISO","code",List.of("0"),List.of(),List.of(),"EXACT",0L,source);assertThat(evaluate("{\"code\":0,\"data\":["+record("room",roster("A"),"2026-10-14T00:00:30Z")+"]}",rules,Set.of("A"))).containsEntry("status","UNKNOWN");}

}
